#include <stdint.h>
#define STM32G474xx
#include "stm32g4xx.h"
#include "adc.h"
#include "kobuki.h"
#include "uart.h"
#include "ultrasonic.h"
#include "pathfind.h"
#include "navigation.h"
#include "decision.h"

/* Kobuki button values */
#define BUTTON_0_START  0x01U
#define BUTTON_1_STOP   0x02U
#define BUTTON_2_ROTATE 0x04U

#define A_ROTATION 90
#define B_ROTATION -90
#define A_DISTANCE_1 10000 // yet to be determined
#define A_DISTANCE_2 10000 // yet to be determined
#define B_DISTANCE_1 10000 // yet to be determined
#define B_DISTANCE_2 10000 // yet to be determined

// Logic
#define FALSE 0
#define TRUE 1

// States
typedef enum { 
    IDLE,
    ORIENT,
    DECISION,
    ALIGN,
    PATHFIND,
    STORAGE,
    DEPOSIT
 } fsm_state; // far more to be added

typedef enum {
    ORIENT_SCANNING,
    ORIENT_TURNING
} OrientStep;




int main() {
    OrientStep orient_step = ORIENT_SCANNING;
    fsm_state current_state = IDLE;

    Kobuki_Typedef kobuki;
    US_Typedef ultrasonic;
    NavigationScan navigation_object;
    // Kobuki_LED_Enum led_1, led_2;
    
    /* Require button release before accepting another start. */
    uint8_t start_ready = 0U;

    UART_Init(); 
    ADC_Init();
    Ultrasonic_Init();

    while (1) {
        Kobuki_Read(&kobuki);
        Ultrasonic_Detect(&ultrasonic);

        /* Global stop conditions take priority over the FSM. */
        if ((kobuki.wheeldrop != 0U) ||
            ((kobuki.button & BUTTON_1_STOP) != 0U)) {
            Kobuki_Drive(0);
            current_state = IDLE;
            start_ready = 0U;
            continue;
        }

        switch (current_state) {
            case IDLE:
                Kobuki_Drive(0);

                if (kobuki.button == 0U) {
                    start_ready = 1U;
                }

                if ((start_ready != 0U) &&
                    ((kobuki.button & BUTTON_0_START) != 0U)) {
                    Navigation_Scan_Start(&navigation_object, kobuki.angle, ultrasonic.detected);
                    start_ready = 0U;
                    orient_step = ORIENT_SCANNING;
                    current_state = ORIENT;
                }
                break;

            case ORIENT:
                switch (orient_step) {
                    case ORIENT_SCANNING:
                        Navigation_Scan_Update(
                            &navigation_object,
                            kobuki.angle,
                            ultrasonic.detected
                        );

                        if (navigation_object.state == SCAN_COMPLETE) {
                            Navigation_Orient_Start(
                                navigation_object.midpoint
                            );

                            orient_step = ORIENT_TURNING;
                        }
                        else if (navigation_object.state == SCAN_FAILED) {
                            Kobuki_Drive(0);
                            current_state = IDLE;
                        }
                        break;

                    case ORIENT_TURNING:
                        if (Navigation_Orient_Update(&kobuki) != 0U) {
                            Kobuki_Drive(0);
                            current_state = DECISION;
                        }
                        break;

                    default:
                        Kobuki_Drive(0);
                        current_state = IDLE;
                        break;
                }
                break;
            case DECISION:
                if (LayoutA(ultrasonic.range_mm)) {
                    path_angle = A_ROTATION;
                    path_first_drive_distance = A_DISTANCE_1;
                    path_second_drive_distance = A_DISTANCE_2;
                    current_state = ALIGN;
                } else if (LayoutB(ultrasonic.range_mm)) {
                    path_angle = B_ROTATION;
                    path_first_drive_distance = B_DISTANCE_1;
                    path_second_drive_distance = B_DISTANCE_2;
                    current_state = ALIGN;
                }
                break;
            case PATHFIND:
            case STORAGE:
            case DEPOSIT:
                /* Keep stopped until these states are connected. */
                Kobuki_Drive(0);
                break;

            default:
                Kobuki_Drive(0);
                current_state = IDLE;
                start_ready = 0U;
                break;
        }
    }
}


